import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type HighDeductiblePlanProps = Record<string, any>;

const HighDeductiblePlan: React.FC<HighDeductiblePlanProps> = ({
  backgroundColor = "#F7F9FC",
  transparentBackground = false,
  durationInSeconds = 10,
  step1Color = "#4D96FF", // Blue
  step2Color = "#FF6B6B", // Red
  step3Color = "#28C76F", // Green
  arrowColor = "#CBD5E1",
  textColor = "#1E2A38",
  step1Text = "Low Premium",
  step2Text = "Pay Bills First",
  step3Text = "Insurance Helps Later",
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["DM Sans"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Layout Calculations
  const s = Math.min(width, height);
  const centerX = width / 2;
  
  // Icon sizes remain large, strictly preserving visual footprint
  const circleRadius = width * 0.155; 
  
  // Centered & Balanced Vertical Stack Spacing
  // Tighter grouping (30% spread instead of 36%), exactly centered to guarantee equal top/bottom padding
  const step1Y = height * 0.173;
  const step2Y = height * 0.473;
  const step3Y = height * 0.773;

  // SVG Icon Components (Scaled slightly to 60% inside the circle to maintain large icon feel)
  const CoinIcon = () => (
    <svg viewBox="0 0 24 24" fill="white" width="60%" height="60%" style={{ transition: "none" }}>
      <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1.41 16.09V20h-2.67v-1.93c-1.71-.36-3.16-1.46-3.27-3.4h1.96c.1 1.05.82 1.87 2.65 1.87 1.96 0 2.4-.98 2.4-1.59 0-.83-.44-1.61-2.67-2.14-2.48-.6-4.18-1.62-4.18-3.67 0-1.72 1.39-2.84 3.11-3.21V4h2.67v1.95c1.86.45 2.79 1.86 2.85 3.39H14.3c-.05-1.11-.64-1.87-2.22-1.87-1.5 0-2.4.68-2.4 1.64 0 .84.65 1.39 2.67 1.91s4.18 1.39 4.18 3.91c-.01 1.83-1.38 2.83-3.12 3.16z"/>
    </svg>
  );

  const BillIcon = () => (
    <svg viewBox="0 0 24 24" fill="white" width="60%" height="60%" style={{ transition: "none" }}>
      <path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm-1 13v3h-2v-3H8v-2h3v-3h2v3h3v2h-3zm-1-6V3.5L16.5 9H12z"/>
    </svg>
  );

  const ShieldIcon = () => (
    <svg viewBox="0 0 24 24" fill="white" width="60%" height="60%" style={{ transition: "none" }}>
      <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm-2 16l-4-4 1.41-1.41L10 14.17l6.59-6.59L18 9l-8 8z"/>
    </svg>
  );

  // Staggered Sequential Timings
  const stepsData = [
    { id: 1, text: step1Text, color: step1Color, icon: CoinIcon, y: step1Y, springFrame: 10 },
    { id: 2, text: step2Text, color: step2Color, icon: BillIcon, y: step2Y, springFrame: 50 },
    { id: 3, text: step3Text, color: step3Color, icon: ShieldIcon, y: step3Y, springFrame: 115 },
  ];

  // Vertical Arrow Generation Logic (Perfectly centered in visual gaps)
  const getArrowData = (startIdx: number, endIdx: number, drawStartFrame: number) => {
    // Top boundary accounts precisely for the lower footprint of the text label
    const topBoundary = stepsData[startIdx].y + circleRadius + height * 0.055;
    // Bottom boundary marks just slightly above the next circle
    const bottomBoundary = stepsData[endIdx].y - circleRadius - height * 0.01;
    
    // Find the exact mathematical midpoint of the vertical whitespace
    const gapCenterY = (topBoundary + bottomBoundary) / 2;
    const availableHeight = Math.max(0, bottomBoundary - topBoundary);
    
    // Size the arrow to take up 55% of the empty space, ensuring perfectly equal padding above and below it
    const aHeight = availableHeight * 0.55;
    const startY = gapCenterY - aHeight / 2;

    const progress = interpolate(frame, [drawStartFrame, drawStartFrame + 15], [0, 1], { 
      extrapolateRight: "clamp", 
      extrapolateLeft: "clamp", 
      easing: Easing.out(Easing.quad) 
    });
    
    return { startY, aHeight, progress };
  };

  const arrow1 = getArrowData(0, 1, 30);
  const arrow2 = getArrowData(1, 2, 95);

  const drawArrow = (arrow: { startY: number, aHeight: number, progress: number }) => {
    if (arrow.aHeight <= 0) return null;
    
    const arrowWidth = s * 0.08;
    const lineThickness = s * 0.012;
    const headSize = s * 0.025;
    const arrowX = centerX - arrowWidth / 2;

    return (
      <svg style={{ position: "absolute", top: arrow.startY, left: arrowX, width: arrowWidth, height: arrow.aHeight, transition: "none", overflow: "visible", zIndex: 0 }}>
        <line
          x1={arrowWidth / 2} y1="0"
          x2={arrowWidth / 2} y2={Math.max(0, arrow.aHeight - headSize)}
          stroke={arrowColor}
          strokeWidth={lineThickness}
          strokeLinecap="round"
          strokeDasharray={arrow.aHeight}
          strokeDashoffset={arrow.aHeight * (1 - arrow.progress)}
          style={{ transition: "none" }}
        />
        <polygon
          points={`${arrowWidth / 2 - headSize / 1.5},${arrow.aHeight - headSize} ${arrowWidth / 2},${arrow.aHeight} ${arrowWidth / 2 + headSize / 1.5},${arrow.aHeight - headSize}`}
          fill={arrowColor}
          opacity={arrow.progress > 0.8 ? (arrow.progress - 0.8) * 5 : 0}
          style={{ transition: "none" }}
        />
      </svg>
    );
  };

  // Flying Coins Animation from Step 1 to Step 2 (Vertical Fall)
  const renderFlyingCoins = () => {
    return [0, 1, 2].map((i) => {
      const startFrame = 65 + i * 8; // Stagger coins
      const progress = interpolate(frame - startFrame, [0, 25], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
      
      if (progress === 0 || progress === 1) return null;

      const currentY = interpolate(progress, [0, 1], [step1Y, step2Y]);
      // Sine wave creates a nice parabolic arc bowing to the right side
      const arcX = Math.sin(progress * Math.PI) * (width * 0.25);
      const currentX = centerX + arcX;
      
      const rotation = interpolate(progress, [0, 1], [0, 360]);
      const opacity = interpolate(progress, [0, 0.2, 0.8, 1], [0, 1, 1, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
      
      const coinSize = s * 0.08;

      return (
        <div key={`coin-${i}`} style={{
          position: "absolute",
          top: currentY - coinSize / 2,
          left: currentX - coinSize / 2,
          width: coinSize,
          height: coinSize,
          backgroundColor: "#FBBF24", // Vibrant Gold
          borderRadius: "50%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `rotate(${rotation}deg)`,
          boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
          opacity: opacity,
          zIndex: 10,
          transition: "none"
        }}>
          <span style={{ color: "#B45309", fontWeight: "bold", fontSize: coinSize * 0.55, transition: "none", lineHeight: 1 }}>$</span>
        </div>
      );
    });
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "DM Sans", transition: "none" }}>
      
      {/* Background layer for Arrows */}
      {drawArrow(arrow1)}
      {drawArrow(arrow2)}

      {/* Foreground layer for Sequential Steps */}
      {stepsData.map((step) => {
        // Dynamic "pop in" scale
        const scale = spring({ frame: frame - step.springFrame, fps, config: { damping: 10 } });
        const textOpacity = interpolate(frame, [step.springFrame + 5, step.springFrame + 25], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
        const textY = interpolate(frame, [step.springFrame + 5, step.springFrame + 25], [30, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp", easing: Easing.out(Easing.quad) });

        return (
          <div key={step.id} style={{ position: "absolute", top: step.y - circleRadius, left: centerX - circleRadius, width: circleRadius * 2, height: circleRadius * 2, transition: "none", zIndex: 5 }}>
            
            {/* Bold Colored Circle with Icon */}
            <div style={{ width: "100%", height: "100%", backgroundColor: step.color, borderRadius: "50%", display: "flex", justifyContent: "center", alignItems: "center", transform: `scale(${scale})`, boxShadow: "0 12px 36px rgba(0,0,0,0.12)", transition: "none", position: "relative" }}>
              {step.icon()}
            </div>

            {/* Step Label aligned directly below the circle */}
            <div style={{ position: "absolute", top: circleRadius * 2 + height * 0.015, left: -width * 0.4 + circleRadius, width: width * 0.8, textAlign: "center", opacity: textOpacity, transform: `translateY(${textY}px)`, transition: "none" }}>
              <span style={{ fontSize: s * 0.055, fontWeight: 700, color: textColor, lineHeight: 1.25, transition: "none", margin: 0, display: "block", textWrap: "balance" as any }}>
                {step.text}
              </span>
            </div>
            
          </div>
        );
      })}

      {/* Animated elements flying between steps */}
      {renderFlyingCoins()}

    </AbsoluteFill>
  );
};

export default HighDeductiblePlan;